import hashlib,json,subprocess
from pathlib import Path
from datetime import datetime,timezone
root=Path(__file__).resolve().parents[1]
digest='95673edcdf2463fe9902d7abb6a39c946220df56f98af82db548f6a423b4b9e4'
path='mod_nailong/assets/generated_fullsize/'+digest+'.png'
def git(*args):return subprocess.check_output(['git',*args],cwd=root)
out={'observed_at_utc':datetime.now(timezone.utc).isoformat(),'target_sha256':digest,'commits':[]}
for commit in ['b7daaa22f90c56af253b3b81144940a329905447','076360191607f282a4c0cdb8500c4b1d13971493']:
    index=json.loads(git('show',commit+':mod_nailong/data/fullsize-files.json'))
    tree={}
    for line in git('ls-tree','-r','-l',commit).decode('utf-8').splitlines():
        info,tree_path=line.split('\t',1)
        fields=info.split()
        tree[tree_path]={'mode':fields[0],'type':fields[1],'blob':fields[2],'bytes':int(fields[3]) if fields[3]!='-' else None}
    problems=[]
    for key,entry in index['outputs'].items():
        item=tree.get(entry['path'])
        if not item or item['type']!='blob' or item['bytes']!=entry['bytes']:
            problems.append({'digest':key,'index':entry,'tree':item})
    rec={'commit':commit,'index_count':index['count'],'target_index':index['outputs'].get(digest),'target_tree':tree.get(path),'all_index_tree_size_problems':problems}
    if path in tree:
        raw=git('show',commit+':'+path)
        rec['target_actual_sha256']=hashlib.sha256(raw).hexdigest()
        rec['target_actual_bytes']=len(raw)
    out['commits'].append(rec)
live=root/path
out['workspace_target']={'exists':live.is_file()}
if live.is_file():out['workspace_target'].update(bytes=live.stat().st_size,sha256=hashlib.sha256(live.read_bytes()).hexdigest())
dest=root/'runtime/resume-low-20261025/raw-mismatch-observation.json'
dest.write_text(json.dumps(out,ensure_ascii=True,indent=2)+'\n',encoding='utf-8')
print(json.dumps(out,ensure_ascii=True))

